#[derive(Clone, Copy, Debug)]
enum Cast80Step {
    Start,
    OnTimeOver1,
    OnTimeOver2,
    OnNomal1,
    OnNomal2,
}

fn cast_80_run(ctx: &Ctx, mut step: Cast80Step, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            Cast80Step::Start => {
                step = Cast80Step::OnTimeOver1;
                continue 'machine;
            }
            Cast80Step::OnTimeOver1 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("force_4-1"),
                        Val::from("Arena will be reactivated due to an error occurred during battle."),
                        Val::from(0),
                        Val::from(16764416),
                    ],
                )?;
                return Err(Stop::End);
            }
            Cast80Step::OnTimeOver2 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("force_4-1"),
                        Val::from("Arena will be activated due to an error occurred in the waiting room."),
                        Val::from(0),
                        Val::from(16764416),
                    ],
                )?;
                return Err(Stop::End);
            }
            Cast80Step::OnNomal1 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("force_4-1"),
                        Val::from("Arena will be reactivated."),
                        Val::from(0),
                        Val::from(16764416),
                    ],
                )?;
                return Err(Stop::End);
            }
            Cast80Step::OnNomal2 => {
                ctx.call(
                    Function::MapAnnounce,
                    vec![
                        Val::from("force_4-1"),
                        Val::from("Arena will be reactivated."),
                        Val::from(0),
                        Val::from(16764416),
                    ],
                )?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn cast_80(ctx: &Ctx) -> Script {
    cast_80_run(ctx, Cast80Step::Start, Vec::new()).map(|_| ())
}

